(function () {
  "use strict";

  var prefersReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  function $(sel, ctx) { return (ctx || document).querySelector(sel); }
  function $$(sel, ctx) { return Array.prototype.slice.call((ctx || document).querySelectorAll(sel)); }

  /* ---------- 1. Dark / Light theme ---------- */
  var root = document.documentElement;
  var themeBtn = $("#theme-toggle");
  var sunIcon = $(".icon-sun", themeBtn);
  var moonIcon = $(".icon-moon", themeBtn);

  function currentTheme() {
    return root.getAttribute("data-theme") === "light" ? "light" : "dark";
  }
  function applyTheme(t) {
    root.setAttribute("data-theme", t);
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute("content", t === "dark" ? "#040a15" : "#f3f6fc");
    if (sunIcon && moonIcon) {
      sunIcon.classList.toggle("hidden", t !== "dark");
      moonIcon.classList.toggle("hidden", t === "dark");
    }
    themeBtn.setAttribute("aria-pressed", String(t === "light"));
  }
  applyTheme(currentTheme());
  themeBtn.addEventListener("click", function () {
    var next = currentTheme() === "dark" ? "light" : "dark";
    applyTheme(next);
    try { localStorage.setItem("ag-theme", next); } catch (e) { /* storage unavailable */ }
  });

  /* ---------- 2. Navbar state + scroll progress + back-to-top ---------- */
  var navbar = $("#navbar");
  var progressBar = $("#progress-bar");
  var toTop = $("#to-top");
  var ticking = false;

  function onScroll() {
    var y = window.scrollY || window.pageYOffset;
    navbar.classList.toggle("scrolled", y > 24);
    var docH = document.documentElement.scrollHeight - window.innerHeight;
    var pct = docH > 0 ? Math.min(100, (y / docH) * 100) : 0;
    progressBar.style.width = pct + "%";
    toTop.classList.toggle("show", y > 600);
    ticking = false;
  }
  window.addEventListener("scroll", function () {
    if (!ticking) { window.requestAnimationFrame(onScroll); ticking = true; }
  }, { passive: true });
  onScroll();

  toTop.addEventListener("click", function () {
    window.scrollTo({ top: 0, behavior: prefersReduced ? "auto" : "smooth" });
  });

  /* ---------- 3. Mobile navigation ---------- */
  var navToggle = $("#nav-toggle");
  var navLinks = $("#nav-links");
  var menuIcon = $(".icon-menu", navToggle);
  var closeIcon = $(".icon-x", navToggle);

  function setMenu(open) {
    navLinks.classList.toggle("open", open);
    menuIcon.classList.toggle("hidden", open);
    closeIcon.classList.toggle("hidden", !open);
    navToggle.setAttribute("aria-expanded", String(open));
    navToggle.setAttribute("aria-label", open ? "Close navigation menu" : "Open navigation menu");
  }
  navToggle.addEventListener("click", function () {
    setMenu(!navLinks.classList.contains("open"));
  });
  $$("a", navLinks).forEach(function (a) {
    a.addEventListener("click", function () { setMenu(false); });
  });
  window.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && navLinks.classList.contains("open")) setMenu(false);
  });
  window.addEventListener("resize", function () {
    if (window.innerWidth > 992) setMenu(false);
  });

  /* ---------- 4. Active section highlighting (scrollspy) ---------- */
  var linkMap = {};
  $$("#nav-links a").forEach(function (a) {
    var id = (a.getAttribute("href") || "").slice(1);
    if (id) linkMap[id] = a;
  });
  var spy = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      if (en.isIntersecting) {
        $$("#nav-links a").forEach(function (x) { x.classList.remove("active"); });
        var link = linkMap[en.target.id];
        if (link) link.classList.add("active");
      }
    });
  }, { rootMargin: "-38% 0px -52% 0px", threshold: 0 });
  $$("main section[id]").forEach(function (s) { spy.observe(s); });

  /* ---------- 5. Scroll-triggered reveal animations ---------- */
  var revealEls = $$(".reveal, .reveal-stagger");
  if (prefersReduced || !("IntersectionObserver" in window)) {
    revealEls.forEach(function (el) { el.classList.add("visible"); });
  } else {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) {
          en.target.classList.add("visible");
          io.unobserve(en.target);
        }
      });
    }, { threshold: 0.12, rootMargin: "0px 0px -6% 0px" });
    revealEls.forEach(function (el) { io.observe(el); });
  }

  /* ---------- 6. Animated counters (real data only) ---------- */
  function animateCount(el) {
    var target = parseInt(el.getAttribute("data-count"), 10) || 0;
    if (prefersReduced) { el.textContent = String(target); return; }
    var duration = 1400;
    var start = null;
    function step(ts) {
      if (start === null) start = ts;
      var p = Math.min(1, (ts - start) / duration);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = String(Math.round(eased * target));
      if (p < 1) window.requestAnimationFrame(step);
    }
    window.requestAnimationFrame(step);
  }
  var counters = $$("[data-count]");
  if ("IntersectionObserver" in window) {
    var cio = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) {
          animateCount(en.target);
          cio.unobserve(en.target);
        }
      });
    }, { threshold: 0.4 });
    counters.forEach(function (c) { cio.observe(c); });
  } else {
    counters.forEach(animateCount);
  }

  /* ---------- 7. Image preview modal ---------- */
  var modal = $("#img-modal");
  var modalImg = $("#modal-img");
  var modalCap = $("#modal-caption");
  var lastFocus = null;

  function openModal(src, caption, alt) {
    lastFocus = document.activeElement;
    modalImg.setAttribute("src", src);
    modalImg.setAttribute("alt", alt || "");
    modalCap.textContent = caption || "";
    modal.classList.add("open");
    modal.setAttribute("aria-hidden", "false");
    document.body.classList.add("modal-open");
    var closeBtn = $(".modal-close", modal);
    if (closeBtn) closeBtn.focus();
  }
  function closeModal() {
    modal.classList.remove("open");
    modal.setAttribute("aria-hidden", "true");
    document.body.classList.remove("modal-open");
    if (lastFocus && typeof lastFocus.focus === "function") lastFocus.focus();
  }
  $$(".js-zoom").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var img = $("img", btn);
      if (img) openModal(img.currentSrc || img.getAttribute("src"), btn.getAttribute("data-caption"), img.getAttribute("alt"));
    });
  });
  $$("[data-close-modal]", modal).forEach(function (el) {
    el.addEventListener("click", closeModal);
  });
  window.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && modal.classList.contains("open")) closeModal();
  });

  /* ---------- 8. CV download (original PDF embedded as Base64) ---------- */
  var CV_PDF_BASE64 = "";
  function downloadCV() {
    try {
      var clean = CV_PDF_BASE64.replace(/\s+/g, "");
      var bin = window.atob(clean);
      var bytes = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      var blob = new Blob([bytes], { type: "application/pdf" });
      var url = URL.createObjectURL(blob);
      var a = document.createElement("a");
      a.href = url;
      a.download = "Ahmed_Ghanem_CV.pdf";
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.setTimeout(function () { URL.revokeObjectURL(url); }, 4000);
    } catch (err) {
      if (window.console && console.error) console.error("CV download failed:", err);
    }
  }
  $$(".js-cv-download").forEach(function (b) {
    b.addEventListener("click", downloadCV);
  });

  /* ---------- 9. Dynamic copyright year ---------- */
  var yearEl = $("#year");
  if (yearEl) yearEl.textContent = String(new Date().getFullYear());

  /* ---------- 10. Interactive molecular background ---------- */
  var canvas = $("#hero-canvas");
  if (canvas && !prefersReduced && canvas.getContext) {
    var ctx = canvas.getContext("2d");
    var hero = canvas.parentElement;
    var W = 0, H = 0, dpr = 1, nodes = [], raf = null, running = true;
    var mouse = { x: -9999, y: -9999 };
    var COLORS = ["rgba(92,155,255,0.75)", "rgba(67,220,245,0.75)", "rgba(157,176,203,0.6)"];

    function resize() {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = hero.clientWidth;
      H = hero.clientHeight;
      canvas.width = Math.round(W * dpr);
      canvas.height = Math.round(H * dpr);
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      var count = Math.max(26, Math.min(72, Math.round((W * H) / 24000)));
      nodes = [];
      for (var i = 0; i < count; i++) {
        nodes.push({
          x: Math.random() * W,
          y: Math.random() * H,
          vx: (Math.random() - 0.5) * 0.35,
          vy: (Math.random() - 0.5) * 0.35,
          r: Math.random() * 1.8 + 1.1,
          c: COLORS[i % COLORS.length]
        });
      }
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      var LINK = 150;
      for (var i = 0; i < nodes.length; i++) {
        var n = nodes[i];
        n.x += n.vx;
        n.y += n.vy;
        if (n.x < -20) n.x = W + 20; else if (n.x > W + 20) n.x = -20;
        if (n.y < -20) n.y = H + 20; else if (n.y > H + 20) n.y = -20;
        var dxm = n.x - mouse.x, dym = n.y - mouse.y;
        var dm = Math.sqrt(dxm * dxm + dym * dym);
        if (dm < 130 && dm > 0.001) {
          n.x += (dxm / dm) * 0.6;
          n.y += (dym / dm) * 0.6;
        }
        for (var j = i + 1; j < nodes.length; j++) {
          var m = nodes[j];
          var dx = n.x - m.x, dy = n.y - m.y;
          var d = Math.sqrt(dx * dx + dy * dy);
          if (d < LINK) {
            var a = (1 - d / LINK) * 0.34;
            ctx.strokeStyle = "rgba(92,155,255," + a.toFixed(3) + ")";
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(n.x, n.y);
            ctx.lineTo(m.x, m.y);
            ctx.stroke();
          }
        }
        ctx.fillStyle = n.c;
        ctx.beginPath();
        ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);
        ctx.fill();
      }
      if (running) raf = window.requestAnimationFrame(draw);
    }
    function start() { if (raf === null && running) raf = window.requestAnimationFrame(draw); }
    function stop() { if (raf !== null) { window.cancelAnimationFrame(raf); raf = null; } }

    resize();
    start();
    window.addEventListener("resize", resize);
    hero.addEventListener("pointermove", function (e) {
      var rect = canvas.getBoundingClientRect();
      mouse.x = e.clientX - rect.left;
      mouse.y = e.clientY - rect.top;
    }, { passive: true });
    hero.addEventListener("pointerleave", function () {
      mouse.x = -9999;
      mouse.y = -9999;
    });
    document.addEventListener("visibilitychange", function () {
      if (document.hidden) stop(); else start();
    });
  }
})();
